  queryParamKeys = [],
  catchNotFound = false,
  keyTransform,
  payloadKey,
  returnResourceIdInLocationHeader,
  headers,
}: RequestArgs) {
  return async (query: any = {}, payload: any = {}) => {
    const baseParams = this.#getBaseParams?.() ?? {};

    // Filter query parameters by queryParamKeys
    const queryParams =
      queryParamKeys.length > 0
        ? (pick(query, queryParamKeys) as any)
