    };

    // Transform keys of queryParams
    if (keyTransform) {
      this.#transformKey(queryParams, keyTransform);
    }

    return this.#requestWithParams({
      method,
      path,
      payload,
      urlParams,
      queryParams,
      catchNotFound,
      payloadKey,
